#!/usr/bin/env bash
# install-bailian-search.sh — 一键安装 dsh-web-search-bailian 插件到 DeepSeek Harness
# 用法: bash install-bailian-search.sh
set -euo pipefail

# 跨平台 base64 解码(macOS 用 -D, Linux 用 -d)
if base64 --version >/dev/null 2>&1; then b64d() { base64 -d; }; else b64d() { base64 -D; }; fi

DSH_HOME="${DSH_HOME:-$HOME/.dsh}"
PROFILE="$DSH_HOME/profiles/web"
PLUGIN_NAME="@local/dsh-web-search-bailian"
PLUGIN_DIR="$PROFILE/node_modules/$PLUGIN_NAME"
FALLBACK="$DSH_HOME/profiles/node_modules"
PATCH="$PROFILE/cordis.patch.yml"

echo "== [1/5] 检查 profile 是否已初始化 =="
if [ ! -f "$PROFILE/package.json" ]; then
  echo "❌ 未找到 $PROFILE/package.json。"
  echo "   请先运行一次 'npx @deepseek-ai/dsh web' 让它初始化 profile，"
  echo "   看到 http://127.0.0.1:3080 后 Ctrl-C 停掉，再重新运行本脚本。"
  exit 1
fi
echo "   profile 已就绪。"

echo "== [2/5] 写入插件文件 =="
mkdir -p "$PLUGIN_DIR/lib"
b64d > "$PLUGIN_DIR/package.json" <<'PKG_B64'

PKG_B64
b64d > "$PLUGIN_DIR/lib/index.js" <<'IDX_B64'

IDX_B64
echo "   $PLUGIN_DIR"

echo "== [3/5] 建立跨 profile 可解析的软链 =="
mkdir -p "$FALLBACK"
ln -sfn "$PROFILE/node_modules/@local" "$FALLBACK/@local"
echo "   $FALLBACK/@local -> $PROFILE/node_modules/@local"

echo "== [4/5] 合并 profile patch(幂等) =="
if grep -q "web-search-bailian" "$PATCH" 2>/dev/null; then
  echo "   patch 已包含 web-search-bailian，跳过。"
else
  if [ -f "$PATCH" ]; then sed -i.bak '/^[[:space:]]*\[\][[:space:]]*$/d' "$PATCH" && rm -f "$PATCH.bak"; fi
  cat >> "$PATCH" <<'PATCH_EOF'
- insert:
    - id: web-search-bailian
      name: '@local/dsh-web-search-bailian'
      config:
        apiKeyEnv: BAILIAN_API_KEY
- id: web
  name: '@deepseek-ai/dsh-web'
  config:
    searchProvider: bailian
PATCH_EOF
  echo "   已追加到 $PATCH"
fi

echo "== [5/5] 环境自检 =="
SETTINGS="$DSH_HOME/settings.yaml"
CREDS="$DSH_HOME/.credentials.yaml"
if grep -q "api: openai-completions" "$SETTINGS" 2>/dev/null; then
  echo "   ✔ settings.yaml 已是 openai-completions"
else
  echo "   ⚠ settings.yaml 的 bailian provider 需确保: api: openai-completions"
fi
if grep -q "BAILIAN_API_KEY: sk-" "$CREDS" 2>/dev/null; then
  echo "   ✔ .credentials.yaml 已有 BAILIAN_API_KEY"
else
  echo "   ⚠ 需在 $CREDS 里配置 BAILIAN_API_KEY: sk-xxxx"
fi

echo ""
echo "✅ 安装完成。请重启 'dsh web' 生效。"
echo "   验证: 设置 → 插件 → 插件列表 里应能看到 web-search-bailian(已挂载/已启用)。"
